{
  "findings": [
    {
      "check_id": "CKV_AWS_123",
      "title": "Unhealthy connection termination disabled",
      "resource": "aws_alb_target_group.pass",
      "severity": "MEDIUM",
      "explanation": "Disabling unhealthy connection termination can lead to prolonged exposure to unhealthy targets, potentially causing degraded performance or availability issues."
    }
  ],
  "patched_code": "resource \"aws_alb_target_group\" \"pass\" {\n  name     = \"tf-example-lb-nlb-tg\"\n  port     = 25\n  protocol = \"TCP\"\n  vpc_id   = aws_vpc.main.id\n\n  target_health_state {\n    enable_unhealthy_connection_termination = true\n  }\n}\n",
  "fix_summary": "Enabled unhealthy connection termination to ensure that unhealthy targets are promptly removed from the load balancer, improving reliability and performance."
}
